const fs = require('fs');

const raw = fs.readFileSync('config.json', 'utf8');
const config = JSON.parse(raw || '{}');

if (config.port === undefined) config.port = 3000;
if (config.host === undefined) config.host = '127.0.0.1';

fs.writeFileSync('config.out.json', JSON.stringify(config, null, 2) + '\n');
console.log('wrote config.out.json');

